from solution import lookup

class ContractTests(unittest.TestCase):
    def test_00(self):
        self.assertEqual(lookup({'a/b':[{'~x':7}]}, '/a~1b/0/~0x'),7)
    def test_01(self):
        self.assertEqual(lookup({'':3},'/'),3)
    def test_02(self):
        self.assertEqual(lookup([1],''),[1])
    def test_03(self):
        with self.assertRaises(ValueError): lookup({},'bad')

